class MultilingualLegalEngine:
    def __init__(self):
        self.headings = HEADINGS
        self.replacements = SENTENCE_REPLACEMENTS

    def translate_response(self, text: str, target_lang: str = "en") -> str:
        if not target_lang or target_lang == "en":
            return text

        lang = target_lang.lower()
        translated = text

        # 1. Translate Headings
        if lang in self.headings:
            h = self.headings[lang]
            translated = translated.replace("### Statutory Determination", "### " + h.get("statutory_determination", "Statutory Determination"))
            translated = translated.replace("### Detailed Legal and Regulatory Provisions", "### " + h.get("detailed_provisions", "Detailed Provisions"))
            translated = translated.replace("### Strategic Recommendations and Compliance Roadmap", "### " + h.get("strategic_recommendations", "Strategic Recommendations"))
            translated = translated.replace("**Safe Abstention Notice**", "**" + h.get("safe_abstention", "Safe Abstention Notice") + "**")
            translated = translated.replace("**Partial Statutory Coverage**", "**" + h.get("partial_coverage", "Partial Statutory Coverage") + "**")

        # 2. Apply Substantive Sentence & Paragraph Replacements
        if lang in self.replacements:
            for pattern, repl in self.replacements[lang]:
                translated = re.sub(pattern, repl, translated, flags=re.IGNORECASE)

        return translated
